	@Test
	void unsignedHighProductMatchesIndependentArithmetic() {
		long[] edgeValues = { 0L, 1L, -1L, Long.MIN_VALUE, Long.MAX_VALUE };
		for (long left : edgeValues) {
			for (long right : edgeValues) {
				assertUnsignedHighProduct(left, right);
			}
		}

		Random random = new Random(~RANDOM_SEED);
		for (int sample = 0; sample < 10_000; sample++) {
			assertUnsignedHighProduct(random.nextLong(), random.nextLong());
		}
	}

	@Test
	void componentPairMasksPreserveOrderAndValidation() {
		for (int left = -8; left <= 11; left++) {
			for (int right = -8; right <= 11; right++) {
				int leftIndex = left;
				int rightIndex = right;
				if (left >= 0 && left < 4 && right >= 0 && right < 4 && left != right) {
					assertEquals(referenceComponentPairMask(left, right),
							FrontierLeafProbe.componentPairMask(left, right));
				} else {
					IllegalArgumentException failure = assertThrows(IllegalArgumentException.class,
							() -> FrontierLeafProbe.componentPairMask(leftIndex, rightIndex));
					assertEquals("Frontier component pair must contain two distinct indexes in [0, 3]",
							failure.getMessage());
				}
			}
		}
	}

	@Test
	void repeatedBindingChecksPreserveNestedPairSemantics() {
		long[][] ids = {
				{ 1L, 1L, 1L, 1L },
				{ 1L, 2L, 3L, 4L },
				{ 1L, 2L, 1L, 2L },
				{ 4L, 4L, 2L, 0L }
		};
		for (int boundMask = 0; boundMask <= FrontierLeafProbe.ALL_COMPONENTS; boundMask++) {
			for (int repeatedMask = 0; repeatedMask <= FrontierLeafProbe.ALL_COMPONENT_PAIRS; repeatedMask++) {
				for (long[] values : ids) {
					int currentBoundMask = boundMask;
					int currentRepeatedMask = repeatedMask;
					FrontierLeafProbe probe = new FrontierLeafProbe(FrontierLeafProbe.EXPLICIT, boundMask,
							values[0], values[1], values[2], values[3], repeatedMask);
					assertEquals(referenceContradiction(probe), probe.contradictoryRepeatedBindings(),
							() -> "bound=" + currentBoundMask + ", repeated=" + currentRepeatedMask);
				}
			}
		}
	}

	@Test
	void constructorPreservesMaskValidation() {
		int[] planeMasks = { Integer.MIN_VALUE, -1, 0, 1, 2, 3, 4, Integer.MAX_VALUE };
		int[] boundMasks = { Integer.MIN_VALUE, -1, 0, 1, 15, 16, Integer.MAX_VALUE };
		int[] repeatedMasks = { Integer.MIN_VALUE, -1, 0, 1, 63, 64, Integer.MAX_VALUE };
		for (int planeMask : planeMasks) {
			for (int boundMask : boundMasks) {
				for (int repeatedMask : repeatedMasks) {
					int currentPlaneMask = planeMask;
					int currentBoundMask = boundMask;
					int currentRepeatedMask = repeatedMask;
					boolean valid = planeMask > 0 && (planeMask & ~FrontierLeafProbe.BOTH_PLANES) == 0
							&& boundMask >= 0 && (boundMask & ~FrontierLeafProbe.ALL_COMPONENTS) == 0
							&& repeatedMask >= 0
							&& (repeatedMask & ~FrontierLeafProbe.ALL_COMPONENT_PAIRS) == 0;
					if (valid) {
						new FrontierLeafProbe(planeMask, boundMask, 1L, 1L, 1L, 1L, repeatedMask);
					} else {
						IllegalArgumentException failure = assertThrows(IllegalArgumentException.class,
								() -> new FrontierLeafProbe(
										currentPlaneMask, currentBoundMask, 1L, 1L, 1L, 1L,
										currentRepeatedMask));
						assertEquals("Frontier leaf probe masks or bound term IDs are invalid", failure.getMessage());
					}
				}
			}
		}
	}

	private static void assertUnsignedHighProduct(long left, long right) {
		BigInteger product = unsigned(left).multiply(unsigned(right));
		assertEquals(product.shiftRight(Long.SIZE).longValue(),
				FrontierStatisticsHash.unsignedMultiplyHigh(left, right));
	}

	private static void assertFixedWidthBuckets(int lane, int component, long value, int widthMask,
			int[] destination, int offset, int width) {
		switch (width) {
		case 4 -> FrontierStatisticsHash.omniBuckets4(lane, component, value, widthMask, destination, offset);
		case 8 -> FrontierStatisticsHash.omniBuckets8(lane, component, value, widthMask, destination, offset);
		case 16 -> FrontierStatisticsHash.omniBuckets16(lane, component, value, widthMask, destination, offset);
		default -> throw new AssertionError(width);
		}
		for (int row = 0; row < width; row++) {
			assertEquals(FrontierStatisticsHash.omniBucket(lane, component, row, value, widthMask),
					destination[offset + row]);
		}
	}

	private static void assertFixedWidthPriorities(long rowPriority, long[] destination, int offset, int width) {
		switch (width) {
		case 4 -> FrontierStatisticsHash.omniPriorities4FromRowPriority(rowPriority, destination, offset);
		case 8 -> FrontierStatisticsHash.omniPriorities8FromRowPriority(rowPriority, destination, offset);
		case 16 -> FrontierStatisticsHash.omniPriorities16FromRowPriority(rowPriority, destination, offset);
		default -> throw new AssertionError(width);
		}
		for (int lane = 0; lane < width; lane++) {
			assertEquals(FrontierStatisticsHash.omniPriorityFromRowPriority(lane, rowPriority),
					destination[offset + lane]);
		}
	}

	private static BigInteger unsigned(long value) {
		BigInteger magnitude = BigInteger.valueOf(value & Long.MAX_VALUE);
		return value < 0L ? magnitude.setBit(Long.SIZE - 1) : magnitude;
	}

	private static long referenceMix64(long value) {
		value ^= value >>> 30;
		value *= 0xbf58476d1ce4e5b9L;
		value ^= value >>> 27;
		value *= 0x94d049bb133111ebL;
		return value ^ value >>> 31;
	}

	private static long referenceConditioningKey(int mask, long subject, long predicate, long object, long context) {
		long hash = 0x6a09e667f3bcc909L ^ mask;
		long[] components = { subject, predicate, object, context };
		for (int component = 0; component < components.length; component++) {
			if ((mask & 1 << component) != 0) {
				hash = referenceMix64(hash ^ referenceMix64(components[component] ^ componentSeed(component)));
			}
		}
		return hash;
	}

	private static int referenceBucket(long key, int row, int plane, int mask, int widthMask) {
		long seed = 0x9e3779b97f4a7c15L * (row + 1L)
				^ 0xbf58476d1ce4e5b9L * (mask + 1L)
				^ 0x94d049bb133111ebL * (plane + 1L);
		return (int) referenceMix64(key ^ seed) & widthMask;
	}

	private static long componentSeed(int component) {
		return switch (component) {
		case 0 -> 0x243f6a8885a308d3L;
		case 1 -> 0x13198a2e03707344L;
		case 2 -> 0xa4093822299f31d0L;
		case 3 -> 0x082efa98ec4e6c89L;
		default -> throw new AssertionError(component);
		};
	}

	private static int referenceComponentPairMask(int left, int right) {
		int first = Math.min(left, right);
		int second = Math.max(left, right);
		return switch (first) {
		case 0 -> 1 << second - 1;
		case 1 -> 1 << second + 1;
		case 2 -> FrontierLeafProbe.OBJECT_CONTEXT_EQUAL;
		default -> throw new IllegalArgumentException("Frontier component pair is invalid");
		};
	}

	private static boolean referenceContradiction(FrontierLeafProbe probe) {
		for (int left = 0; left < 4; left++) {
			if ((probe.boundMask() & 1 << left) == 0) {
				continue;
			}
			for (int right = left + 1; right < 4; right++) {
				if ((probe.boundMask() & 1 << right) != 0
						&& (probe.repeatedComponentPairMask() & referenceComponentPairMask(left, right)) != 0
						&& probe.component(left) != probe.component(right)) {
					return true;
				}
			}
		}
		return false;
	}
